import {enrichData,recommend,getSynergy,getChampionTags,TAG_LABELS} from './engine.js';
import {getVersionInfo} from './version.js';
import {createStatisticsView} from './statistics-view.js';
import {createLiveController} from './live.js';
import {createSessionSync} from './session-sync.js';

const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s??'').toLowerCase().replace(/[\s·'’:\-：]/g,'');
const safeUrl=u=>/^https:\/\//.test(u||'')?esc(u):'#';
const rarityNames={silver:'白银',gold:'黄金',prismatic:'棱彩'};
const roleNames={Mage:'法师',Assassin:'刺客',Fighter:'战士',Tank:'坦克',Marksman:'射手',Support:'辅助'};
const routeNames={auto:'跟随英雄机制',attack:'普攻输出',spell:'技能输出',tank:'坦克生存',support:'治疗与辅助',crit:'暴击路线'};
const filters=[['all','全部海克斯'],['attack','普攻'],['spell','技能'],['crit','暴击'],['health','生命值'],['heal','治疗'],['cc','控制'],['haste','技能急速']];
let statisticsView;
let data,champions,augments,champMap,augMap,picker,toastTimer,liveController,sessionSync;
let persisted={};try{persisted=JSON.parse(localStorage.getItem('hexguide-session')||'{}');}catch{}
const state={gameId:persisted.gameId||null,tab:'live',championId:persisted.championId||'',owned:Array.isArray(persisted.owned)?persisted.owned:[],route:routeNames[persisted.route]?persisted.route:'auto',query:'',scope:'snapshot',rarity:'all',tag:'all',sort:'default',limit:24,champQuery:'',champExpanded:false,synergy:[null,null],candidates:[null,null,null],candidateSource:'manual',compared:false,mobileExpanded:true,buildExpanded:false,selectedAugmentId:null};
const currentChampion=()=>champMap.get(String(state.championId));
const ownedAugments=()=>state.owned.map(id=>augMap.get(id)).filter(Boolean);
const save=()=>{try{localStorage.setItem('hexguide-session',JSON.stringify({gameId:state.gameId,championId:state.championId,owned:state.owned,route:state.route}));}catch{}sessionSync?.publish();};
const img=(url,cls='',alt='')=>`<img src="${safeUrl(url)}" class="${cls}" alt="${esc(alt)}" loading="lazy" onerror="this.onerror=null;this.src='./assets/mark.svg'">`;
const tags=a=>(a.tags||[]).filter(t=>TAG_LABELS[t]);
const isReferenceActive=a=>a.availability==='current'&&!a.retiredPatch&&a.recommendable!==false;
const matchText=(item,q)=>!q||norm([item.name,item.title,item.enName,...(item.aliases||[]),item.description,...(item.tags||[]).map(t=>TAG_LABELS[t]||t)].join(' ')).includes(norm(q));
const rank=a=>recommend(a,currentChampion(),ownedAugments(),state.route);
const evidenceText=a=>a.recommendable===false?'赛季之星专属':a.retiredPatch?'历史资料 · 已退场':a.availability==='catalog-only'?'可选状态待核实':a.unresolvedValues?.length?'部分数值待核实':a.description?'效果资料已收录':'效果资料待补充';
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function empty(title,text,action=''){return `<div class="empty"><div class="empty-symbol">◇</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${action}</div>`;}
function versionPanel(){const v=getVersionInfo(data.meta);return `<section class="version-panel" aria-label="数据版本与更新时间" data-ui-id="version-panel" data-ui-label="数据版本栏" data-ui-container="version-panel"><div data-ui-id="version-current" data-ui-label="数据版本"><span class="version-caption">数据版本</span><strong>海克斯大乱斗 ${esc(v.label)}</strong></div><div class="version-updated" data-ui-id="version-updated" data-ui-label="最后更新时间"><span class="version-caption">最后更新时间</span><time datetime="${esc(v.updatedAt||'')}">${esc(v.updatedLabel)}</time></div><button data-action="sources" aria-label="查看各数据来源及版本" data-ui-id="version-sources" data-ui-label="数据说明按钮">数据说明 ⓘ</button></section>`;}
function dataNote(){const v=getVersionInfo(data.meta);return `<div class="data-note" data-ui-id="data-note" data-ui-label="数据与推荐说明提示"><span>ⓘ</span><span>规则 ${esc(v.rulesPatch)}${v.statsLag?`；来源统计仍为 ${esc(v.statsPatch)}，统计日期 ${esc(v.statsDate)}`:'—默认排除历史与状态未确认项'}。此处适配与联动为机制推导。<a href="#stats">英雄与海克斯胜率在英雄胜率页查看</a>。<button data-action="sources">查看来源</button></span></div>`;}

function sessionPanel(){const c=currentChampion();return `<aside class="session-panel" aria-label="本局设置" data-ui-id="session-panel" data-ui-label="我的这一局面板" data-ui-container="session-panel"><div class="session-top" data-action="toggle-session" data-ui-id="session-header" data-ui-label="本局面板标题栏" data-ui-container="session-header"><h2 data-ui-id="session-title" data-ui-label="我的这一局标题">◈　本局选择</h2><button class="text-button" data-action="reset-session" data-ui-id="session-reset" data-ui-label="重置本局按钮">重置</button><button class="mobile-session-toggle" aria-expanded="${state.mobileExpanded}" data-action="toggle-session" data-ui-id="session-mobile-toggle" data-ui-label="手机版展开按钮">${state.mobileExpanded?'收起':'展开设置'} ▾</button></div><div class="session-body ${state.mobileExpanded?'':'collapsed'}" data-ui-id="session-body" data-ui-label="本局设置内容" data-ui-container="session-body"><div data-ui-id="session-hero" data-ui-label="当前英雄选择"><label class="field-label">当前英雄</label><button class="champion-button" data-action="pick-champion">${c?img(c.icon,'champion-avatar'):''}<span><strong>${esc(c?.name||'选择英雄')}</strong><small>${esc(c?.title||'让推荐更贴合')}</small></span><span class="chevron">⌄</span></button></div><div class="session-section" data-ui-id="session-route" data-ui-label="玩法方向选择"><label class="field-label" for="route">玩法方向</label><select id="route" class="route-select">${Object.entries(routeNames).map(([v,n])=>`<option value="${v}" ${state.route===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="session-section owned-section" data-ui-id="session-owned" data-ui-label="本局已选海克斯" data-ui-container="session-owned"><div class="field-label" data-ui-id="session-owned-label" data-ui-label="已选海克斯标题"><span>已选海克斯</span><span>${state.owned.length} 个</span></div><div class="owned-list" data-ui-id="session-owned-list" data-ui-label="已选海克斯列表">${ownedAugments().map(a=>`<div class="owned-item">${img(a.icon)}<span>${esc(a.name)}</span><button data-action="remove-owned" data-id="${esc(a.id)}" aria-label="移除${esc(a.name)}">×</button></div>`).join('')}</div><button class="add-owned" data-action="pick-owned" data-ui-id="session-owned-add" data-ui-label="添加已选海克斯按钮">＋ 添加已选海克斯</button></div><div class="session-tip" data-ui-id="session-tip" data-ui-label="本局设置提示"><b>先看眼前的选项。</b><br>添加已有海克斯，推荐会一起考虑本局的条件联动与冲突。</div><button class="session-cta" type="button" data-action="focus-home-compare" data-ui-id="session-compare" data-ui-label="本局三选一入口"><span>比较本轮三个选项</span><span>↓</span></button></div></aside>`;}
function pageChampionContext(id){const c=currentChampion();return `<div class="page-champion-context" data-ui-id="${id}" data-ui-label="当前英雄与本局条件">${c?img(c.icon):''}<div><strong>${esc(c?.name||'请选择英雄')}</strong><p>${esc(routeNames[state.route])} · 已选 ${state.owned.length} 个海克斯</p></div><button type="button" data-action="pick-champion">切换英雄</button></div>`;}
function heroBanner(){return `<section class="hero-banner" data-ui-id="library-banner" data-ui-label="海克斯库横幅" data-ui-container="library-banner"><div data-ui-id="library-banner-art" data-ui-label="横幅英雄原画" class="hero-art" role="img" aria-label="九尾妖狐阿狸原画"></div><div class="hero-text" data-ui-id="library-banner-copy" data-ui-label="横幅文案" data-ui-container="library-banner-copy"><span class="eyebrow" data-ui-id="library-banner-eyebrow" data-ui-label="横幅开场文字">把选择的主动权，交回你手里</span><h1 data-ui-id="library-banner-title" data-ui-label="横幅大标题">选对海克斯<br>让这一局有点不一样。</h1><p data-ui-id="library-banner-subtitle" data-ui-label="横幅说明">查效果、找搭配、看懂联动。下一次三选一，不再凭感觉。</p><div class="hero-actions" data-ui-id="library-banner-actions" data-ui-label="横幅入口按钮"><a class="primary-button" href="#compare">开始三选一 <span>↗</span></a><a class="secondary-button" href="#champions">查看英雄适配</a></div></div><span class="banner-note" data-ui-id="library-banner-note" data-ui-label="横幅资料提示">◇ 效果资料可查　推荐理由可解释</span></section>`;}
function card(a,{fit=false,index=0}={}){const r=fit?rank(a):null;const owned=state.owned.includes(a.id);return `<article class="augment-card ${esc(a.rarity)}">${fit?`<span class="rank-badge">${r.confidence==='unknown'?'待判断':index<3?'优先参考':'机制匹配'}</span>`:''}<button class="card-body" data-action="detail" data-id="${esc(a.id)}" aria-label="查看${esc(a.name)}详情"><div class="card-head">${img(a.icon,'augment-icon')}<div><h3>${esc(a.name)}</h3><span class="rarity">${esc(rarityNames[a.rarity]||'品质待核实')}</span></div></div><p class="card-description">${esc(a.summary||a.description||'效果资料暂缺，暂不作确定推荐。')}</p><div class="card-tags">${tags(a).slice(0,3).map(t=>`<span class="card-tag">${TAG_LABELS[t]}</span>`).join('')||'<span class="card-tag">特殊机制</span>'}</div>${fit?`<p class="fit-reason">${esc(r.reasons[0])}</p>`:''}</button><div class="card-bottom"><span class="evidence ${fit&&r.confidence!=='unknown'?'good':''}">${fit?'◇ 机制推导':esc(evidenceText(a))}</span><button class="add-button ${owned?'added':''}" ${!isReferenceActive(a)&&!owned?'disabled':''} data-action="toggle-owned" data-id="${esc(a.id)}" aria-label="${owned?'移除已选':'加入本局'}${esc(a.name)}">${owned?'✓ 已选':'＋ 本局'}</button></div></article>`;}
function library(){return `<div class="section-heading" data-ui-id="library-heading" data-ui-label="海克斯库标题"><div><h2>海克斯库 <small>${augments.length} 条资料</small></h2><p class="section-subtitle">从一个海克斯，找到整局的思路。</p></div><span class="subtle-tag">白银 / 黄金 / 棱彩</span></div>${pageChampionContext("library-context")}<div class="toolbar" data-ui-id="library-toolbar" data-ui-label="海克斯库搜索与筛选" data-ui-container="library-toolbar"><label class="search-field" data-ui-id="library-search-field" data-ui-label="海克斯搜索框"><span>⌕</span><input id="library-search" type="search" placeholder="搜索海克斯名称、英文或效果关键词…" aria-label="搜索海克斯" value="${esc(state.query)}" autocomplete="off"></label><select data-ui-id="library-scope-filter" data-ui-label="海克斯资料范围筛选" id="scope-filter" aria-label="资料范围"><option value="snapshot" ${state.scope==='snapshot'?'selected':''}>4.0 常规选择（${augments.filter(isReferenceActive).length}）</option><option value="all" ${state.scope==='all'?'selected':''}>全部资料（含历史）</option></select><select data-ui-id="library-rarity-filter" data-ui-label="海克斯品质筛选" id="rarity-filter" aria-label="品质筛选"><option value="all">全部品质</option>${Object.entries(rarityNames).map(([v,n])=>`<option value="${v}" ${state.rarity===v?'selected':''}>${n}</option>`).join('')}</select><select data-ui-id="library-sort-filter" data-ui-label="海克斯排序选择" id="sort-filter" aria-label="排序方式"><option value="default" ${state.sort==='default'?'selected':''}>目录顺序</option><option value="fit" ${state.sort==='fit'?'selected':''}>当前英雄适配</option></select></div><div data-ui-id="library-tags" data-ui-label="海克斯机制标签筛选" class="filter-pills" aria-label="机制筛选">${filters.map(([v,n])=>`<button class="filter-pill ${state.tag===v?'active':''}" data-action="filter-tag" data-tag="${v}" aria-pressed="${state.tag===v}">${n}</button>`).join('')}</div><div id="library-results" data-ui-id="library-results" data-ui-label="海克斯库结果" data-ui-container="library-results"></div>${dataNote()}`;}
function renderLibraryResults(){let list=augments.filter(a=>(state.scope==='all'||isReferenceActive(a))&&matchText(a,state.query)&&(state.rarity==='all'||a.rarity===state.rarity)&&(state.tag==='all'||tags(a).includes(state.tag)));if(state.sort==='fit')list.sort((a,b)=>rank(b).score-rank(a).score);$('#library-results').innerHTML=`<div class="result-bar" data-ui-id="library-result-count" data-ui-label="海克斯搜索结果统计"><span>找到 <strong>${list.length}</strong> 个海克斯${state.query?`，关键词「${esc(state.query)}」`:''}</span><span>${state.sort==='fit'?`为 ${esc(currentChampion()?.name||'当前英雄')} 按机制适配排序`:'点击卡片看详情，＋ 加入本局'}</span></div><div class="augment-grid" data-ui-id="library-result-cards" data-ui-label="海克斯卡片列表">${list.slice(0,state.limit).map((a,i)=>card(a,{fit:state.sort==='fit',index:i})).join('')||empty('没有找到符合条件的海克斯','试试其他名称或效果关键词，或者清空筛选。','<button data-action="clear-filters">清空筛选</button>')}</div>${list.length>state.limit?`<button data-ui-id="library-load-more" data-ui-label="海克斯加载更多按钮" class="load-more" data-action="load-more">再看 ${Math.min(24,list.length-state.limit)} 个海克斯　⌄</button>`:''}`;}
function championTiles(){const list=champions.filter(c=>matchText(c,state.champQuery));return list.map(c=>`<button class="champion-tile ${String(c.id)===String(state.championId)?'selected':''}" data-action="set-champion" data-id="${esc(c.id)}" aria-pressed="${String(c.id)===String(state.championId)}">${img(c.icon)}<span>${esc(c.name)}</span></button>`).join('')||empty('没有找到这个英雄','可搜索姓名、称号或英文名。');}
function sourceComboSection(c){const list=(data.combos||[]).filter(x=>String(x.championId)===String(c?.id)&&x.augmentIds?.length&&x.augmentIds.every(id=>isReferenceActive(augMap.get(String(id))||{availability:'catalog-only'}))).slice(0,4);if(!list.length)return '';return `<div data-ui-id="champions-source-heading" data-ui-label="来源搭配标题" class="section-heading" style="margin-top:26px"><h2>来源目录中的搭配 <small>补充参考</small></h2></div><p class="synergy-legend" data-ui-id="champions-source-note" data-ui-label="来源搭配说明">来源目录 ${esc(data.meta.comboPatch||data.meta.statsPatch||data.meta.patch)} 收录的英雄与海克斯关联，可查看原文。目录收录不代表本版实测联动或强度。</p><div class="combo-suggestions" data-ui-id="champions-source-cards" data-ui-label="来源搭配卡片">${list.map(x=>{const items=x.augmentIds.map(id=>augMap.get(String(id)));return `<article class="combo-card"><div class="combo-card-head">${items.slice(0,3).map(a=>img(a.icon)).join('')}<strong>${items.map(a=>esc(a.name)).join(' ＋ ')}</strong></div><p>${esc(c.name)} 的来源关联。需核对英雄机制、任务条件与适用版本。</p><div class="source-combo-actions"><button data-action="detail" data-id="${esc(items[0].id)}">查看效果</button>${items.length>1?`<button data-action="set-pair" data-a="${esc(items[0].id)}" data-b="${esc(items[1].id)}">核对联动</button>`:''}<a href="${safeUrl(x.sourceUrl||x.url)}" target="_blank" rel="noopener noreferrer">来源原文 ↗</a></div></article>`}).join('')}</div>`;}
function championPage(){const c=currentChampion();const list=[...augments].filter(a=>isReferenceActive(a)&&!state.owned.includes(a.id)).sort((a,b)=>rank(b).score-rank(a).score).slice(0,18);return `<div class="page-intro" data-ui-id="champions-intro" data-ui-label="英雄适配标题说明"><h1>英雄适配</h1><p>从英雄机制出发，找到适合这一局的强化方向。</p></div><section class="champion-profile" data-ui-id="champions-profile" data-ui-label="英雄适配当前英雄">${c?img(c.icon):''}<div><h2>${esc(c?.name||'请选择英雄')}<small>${esc(c?.title||'')}</small></h2><div class="profile-tags">${getChampionTags(c).filter(t=>TAG_LABELS[t]).slice(0,5).map(t=>`<span>${TAG_LABELS[t]}</span>`).join('')}</div></div><button class="secondary-button" data-action="toggle-champions">${state.champExpanded?'收起英雄':'切换英雄'} ⌄</button></section>${state.champExpanded?`<section class="hero-picker-section" data-ui-id="champions-picker" data-ui-label="英雄选择列表"><label class="search-field" style="margin-bottom:12px"><span>⌕</span><input id="champ-search" type="search" value="${esc(state.champQuery)}" placeholder="搜索英雄名称、称号、昵称、英文名…" aria-label="搜索英雄"></label><div class="champion-grid" id="champion-grid">${championTiles()}</div></section>`:''}<div class="fit-info" data-ui-id="champions-fit-note" data-ui-label="英雄推荐规则说明"><span>◇</span><div><strong>${esc(c?.name||'当前英雄')} · ${esc(routeNames[state.route])}</strong><br>以下按英雄机制、玩法方向与已选海克斯综合排序。是选择参考，不是胜率排名；点击卡片查看适用条件。</div></div><div class="section-heading" data-ui-id="champions-heading" data-ui-label="英雄适配推荐标题"><h2>值得优先考虑 <small>适配推荐</small></h2><span class="subtle-tag">机制推导</span></div><div class="augment-grid" data-ui-id="champions-cards" data-ui-label="英雄适配海克斯卡片">${list.map((a,i)=>card(a,{fit:true,index:i})).join('')}</div>${sourceComboSection(c)}${dataNote()}`;}
function choiceBox(id,slot){const a=augMap.get(id);return `<button class="choice-box ${a?'selected':''}" data-action="pick-synergy" data-slot="${slot}" aria-label="选择第${slot+1}个联动海克斯">${a?img(a.icon,'augment-icon'):'<span class="choice-placeholder">＋</span>'}<span><strong>${a?esc(a.name):`选择${slot===0?'第一个':'第二个'}海克斯`}</strong><small>${a?`${rarityNames[a.rarity]||''}　点击更换`:'从海克斯库中选择'}</small></span></button>`;}
function catalogAssociation(a,b){const combo=(data.combos||[]).find(x=>(x.augmentIds||[]).map(String).includes(a.id)&&(x.augmentIds||[]).map(String).includes(b.id)&&(!x.championId||String(x.championId)===String(state.championId)));return combo;}
function synergyResult(a,b){const r=getSynergy(a,b,currentChampion());const association=catalogAssociation(a,b);const status={strong:'机制联动',conditional:'有条件联动',conflict:'存在冲突',unknown:'联动待验证'};return `<section class="synergy-result" data-ui-id="synergy-result" data-ui-label="联动查询结果"><span class="result-status ${r.level==='conflict'?'conflict':''}">◇ ${status[r.level]||'待验证'}</span><h2>${r.level==='unknown'?'先核对条件，再决定搭配':r.level==='conflict'?'这两个选择需要谨慎搭配':'看懂这条联动如何成立'}</h2><p>${esc(r.reason)}</p>${r.chain?`<div class="chain">${String(r.chain).split(' → ').map((x,i)=>`${i?'<b>→</b>':''}<span>${esc(x)}</span>`).join('')}</div>`:''}${r.conditions?.length?`<ul class="condition-list">${r.conditions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p class="association-note">结论依据：${r.evidence==='documented'?'来源明确记录':'效果文字与规则推导，未实测'}。${association?`该组合出现在 <a href="${safeUrl(association.sourceUrl||association.url)}" target="_blank" rel="noopener noreferrer">来源组合目录</a> 中；收录不代表实测强度。`:''}</p><div class="dialog-actions"><button class="secondary-button" data-action="detail" data-id="${esc(a.id)}">查看前者效果</button><button class="secondary-button" data-action="detail" data-id="${esc(b.id)}">查看后者效果</button></div></section>`;}
function synergySuggestions(){const anchor=augMap.get(state.synergy[0]);let pairs=[];if(anchor){pairs=augments.filter(a=>isReferenceActive(a)&&a.id!==anchor.id).map(a=>({a:anchor,b:a,r:getSynergy(anchor,a,currentChampion())})).filter(x=>x.r.level==='conditional'||x.r.level==='strong').slice(0,8);}else{const available=augments.filter(a=>isReferenceActive(a)&&(a.effects?.length||a.description));outer:for(const a of available){for(const b of available){if(a.id>=b.id)continue;const r=getSynergy(a,b,currentChampion());if(r.level==='conditional'){pairs.push({a,b,r});break;}}if(pairs.length>=6)break outer;}}return `<div class="section-heading" data-ui-id="synergy-heading" data-ui-label="联动搭配建议标题"><h2>${anchor?'可以继续探索的搭配':'先从这些机制链开始'} <small>条件式参考</small></h2></div><p class="synergy-legend" data-ui-id="synergy-note" data-ui-label="联动搭配建议说明">以下为效果机制推导。触发对象、内置冷却与版本规则，都会影响组合是否成立。</p><div class="combo-suggestions" data-ui-id="synergy-cards" data-ui-label="联动搭配建议卡片">${pairs.map(({a,b,r})=>`<button class="combo-card" data-action="set-pair" data-a="${esc(a.id)}" data-b="${esc(b.id)}"><div class="combo-card-head">${img(a.icon)}<span>＋</span>${img(b.icon)}<strong>${esc(a.name)} ＋ ${esc(b.name)}</strong></div><p>${esc(r.chain||r.reason)}</p><small>◇ 有条件联动　查看成立条件 ↗</small></button>`).join('')||empty('暂未识别到明确的机制链','可以手动选择第二个海克斯查看。没有识别到，不代表游戏中一定不存在联动。')}</div>`;}
function synergyPage(){const a=augMap.get(state.synergy[0]),b=augMap.get(state.synergy[1]);return `<div class="page-intro" data-ui-id="synergy-intro" data-ui-label="联动查询标题说明"><h1>联动查询</h1><p>两个效果放在一起，为什么更有用？把触发链拆开看。</p></div>${pageChampionContext("synergy-context")}<div class="choice-area" data-ui-id="synergy-choices" data-ui-label="联动海克斯选择">${choiceBox(state.synergy[0],0)}<div class="choice-link">⌘</div>${choiceBox(state.synergy[1],1)}</div>${a&&b?synergyResult(a,b):'<div class="fit-info" data-ui-id="synergy-empty-note" data-ui-label="联动未选择说明"><span>⌘</span><div><strong>先选两个海克斯。</strong><br>查看效果之间的触发关系、成立条件和潜在冲突。</div></div>'}${synergySuggestions()}${dataNote()}`;}
function tripleSlot(id,slot){const a=augMap.get(id);return `<div class="triple-slot ${a?'selected':''}"><span class="slot-number">候选 ${slot+1}</span>${a?`<button class="remove-slot" data-action="remove-candidate" data-slot="${slot}" aria-label="移除候选${slot+1}">×</button>${img(a.icon,'augment-icon')}<h3>${esc(a.name)}</h3><span class="rarity" style="--rarity:${a.rarity==='gold'?'var(--gold)':a.rarity==='prismatic'?'var(--pink)':'var(--silver)'}">${rarityNames[a.rarity]||''}</span><button class="slot-change" data-action="pick-candidate" data-slot="${slot}">更换选项</button>`:`<button class="slot-add" data-action="pick-candidate" data-slot="${slot}" aria-label="添加候选${slot+1}">＋</button><span class="slot-helper">选择本轮出现的<br>第 ${slot+1} 个海克斯</span><button class="slot-change" data-action="pick-candidate" data-slot="${slot}">添加选项</button>`}</div>`;}
function compareResults(prefix='compare'){const list=state.candidates.map(id=>augMap.get(id)).filter(Boolean).map(a=>({a,r:rank(a)})).sort((a,b)=>b.r.score-a.r.score);const same=list.length>1&&list[0].r.score===list[1].r.score;return `<div class="section-heading" data-ui-id="${prefix}-result-heading" data-ui-label="三选一结果标题"><h2>这一轮，这样选 <small>结合本局条件</small></h2><button class="text-button" data-action="clear-candidates">重新选择</button></div>${same?'<div class="fit-info" data-ui-id="${prefix}-tie-note" data-ui-label="三选一并列提示"><span>ⓘ</span><div>前两项的规则评分相同，目前无法区分优先级。请结合触发条件与操作习惯选择。</div></div>':''}<div class="recommendation-list" data-ui-id="${prefix}-results" data-ui-label="三选一推荐结果">${list.map(({a,r},i)=>`<article class="recommendation ${i===0?'top-choice':''}"><div class="position-number">${i+1}</div><div><h3>${esc(a.name)} <span>${r.confidence==='unknown'?'适配关系待判断':r.conflicts.length?'存在冲突':i===0?same?'并列参考':'当前优先参考':'结合条件考虑'}</span></h3><ul>${r.reasons.filter(x=>!x.includes('以上是基于')).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${r.cautions.length?`<div class="caution">注意：${r.cautions.map(esc).join(' ')}</div>`:''}<div class="recommendation-bottom"><small>机制推导 · 统计胜率见英雄胜率页</small><button data-action="adopt-candidate" data-id="${esc(a.id)}">选它，加入本局 ＋</button></div></div></article>`).join('')}</div>`;}
function comparePage(){const c=currentChampion();return `<div class="page-intro" data-ui-id="compare-intro" data-ui-label="三选一标题说明"><h1>这一轮，选哪个？</h1><p>填入眼前的三个选项，让英雄机制和已有搭配帮你做判断。</p></div><div class="compare-context" data-ui-id="compare-context" data-ui-label="三选一当前英雄与条件">${c?img(c.icon):''}<div><strong>${esc(c?.name||'尚未选择英雄')}</strong><p>${esc(routeNames[state.route])} · 已选 ${state.owned.length} 个海克斯</p></div><button data-action="pick-champion">更换英雄 ↗</button></div><div class="triple-grid" data-ui-id="compare-slots" data-ui-label="三选一候选选择">${state.candidates.map(tripleSlot).join('')}</div><div class="compare-actions" data-ui-id="compare-actions" data-ui-label="三选一比较操作"><small>请填入三个不同的候选项。<br>已选海克斯会自动参与联动与冲突判断。</small><button class="primary-button" data-action="compare" ${state.candidates.every(Boolean)?'':'disabled'}>比较这三个选项 ⚡</button></div>${state.compared?compareResults():empty('先把本轮选项放进来','选择完成后，会分别解释适配理由、组合条件与需要注意的限制。')} ${dataNote()}`;}
function livePage(){return `<div id="live-content" data-ui-id="live-content" data-ui-label="我的这一局同步与推荐" data-ui-container="live-content">${liveController?.html()||'正在连接本机助手…'}</div>${homeCompare()}`;}
function homeOffer(id,slot){const a=augMap.get(id);if(!a)return `<article class="triple-slot live-offer-waiting"><span class="slot-number">游戏选项 ${slot+1}</span><span class="live-offer-pending" aria-hidden="true">◇</span><h3>等待识别</h3><p>游戏出现海克斯升级时自动显示</p></article>`;const result=rank(a);return `<article class="triple-slot selected live-offer-card"><span class="slot-number">游戏选项 ${slot+1}</span>${img(a.icon,'augment-icon')}<h3>${esc(a.name)}</h3><span class="rarity">${esc(rarityNames[a.rarity]||'')}</span><p class="live-offer-reason">${esc(result.reasons[0]||'结合当前英雄与已选海克斯比较。')}</p>${result.cautions[0]?`<small class="live-offer-caution">${esc(result.cautions[0])}</small>`:''}<button class="primary-button" data-action="adopt-candidate" data-id="${esc(a.id)}">我选了这个</button></article>`;}
function homeCompare(){const complete=state.candidates.every(id=>augMap.has(id));return `<section id="home-compare" class="home-compare" aria-label="本轮三选一" data-ui-id="home-compare" data-ui-label="首页本轮三选一" data-ui-container="home-compare"><div class="section-heading" data-ui-id="home-compare-heading" data-ui-label="首页三选一标题"><div><h2>本轮三选一</h2><p class="section-subtitle">${complete?'按游戏里的顺序展示。你选定后点一下，立即展开本局出装与后续海克斯。':'等待游戏内海克斯升级。后台识别到完整三个选项后会自动比较。'}</p></div><a class="text-button" href="#compare">手动比较工具 ↗</a></div><div class="triple-grid" data-ui-id="home-compare-slots" data-ui-label="首页三选一候选项">${state.candidates.map(homeOffer).join('')}</div><div class="compare-actions" data-ui-id="home-compare-actions" data-ui-label="首页三选一比较操作"><small>${complete?(state.candidateSource==='ocr'?'游戏画面识别 · 请核对名称。':'手动补录候选 · 请核对本轮。')+'这里只记录你的选择，不会操作游戏。':'保持游戏在前台；也可以在侧栏查看并确认。'}</small></div><details class="home-manual-fallback"><summary>识别不准确？手动补录或更正</summary><p>仅在识别失败时使用。独立三选一工具保留完整的手动比较。</p><div class="triple-grid">${state.candidates.map(tripleSlot).join('')}</div><button class="secondary-button" data-action="compare" ${complete?'':'disabled'}>比较手动选项</button></details>${state.compared?compareResults('home-compare'):''}</section>`;}
function statisticsPage(){return statisticsView?.html()||'';}
function render(){const labels={live:'我的这一局',library:'海克斯库',champions:'英雄适配',stats:'英雄胜率',synergy:'联动查询',compare:'三选一推荐'},nav=Object.keys(labels);state.tab=nav.includes(location.hash.slice(1))?location.hash.slice(1):'live';document.querySelectorAll('[data-nav]').forEach(x=>{const active=x.dataset.nav===state.tab;x.classList.toggle('active',active);active?x.setAttribute('aria-current','page'):x.removeAttribute('aria-current');});$('#app').innerHTML=`${versionPanel()}${state.tab==='library'?heroBanner():''}<div class="workspace ${state.tab==='live'?'workspace-home':'workspace-tool'}" data-ui-id="workspace" data-ui-label="当前功能布局" data-ui-container="workspace">${state.tab==='live'?sessionPanel():''}<section class="main-content" aria-label="${labels[state.tab]}" data-ui-id="main-content" data-ui-label="当前功能页面" data-ui-container="main-content">${({live:livePage,library,champions:championPage,stats:statisticsPage,synergy:synergyPage,compare:comparePage})[state.tab]()}</section></div>`;if(state.tab==='library')renderLibraryResults();document.title=`${labels[state.tab]} · 海克斯指南`;}
function renderKeepingFocus(){const active=document.activeElement;const focus=active?.id?'#'+active.id:active?.dataset?.liveAction?'[data-live-action='+JSON.stringify(active.dataset.liveAction)+']':active?.dataset?.action?'[data-action='+JSON.stringify(active.dataset.action)+']'+(active.dataset.id?'[data-id='+JSON.stringify(active.dataset.id)+']':''):null;render();if(focus)$(focus)?.focus({preventScroll:true});}
function addOwned(id){if(!augMap.has(id)||!isReferenceActive(augMap.get(id))||state.owned.includes(id))return false;state.owned.push(id);state.candidates=state.candidates.map(value=>value===id?null:value);state.compared=false;save();return true;}
function pick(kind,slot){picker={kind,slot};$('#picker-title').textContent=kind==='champion'?'选择当前英雄':kind==='owned'?'添加已选海克斯':kind==='synergy'?`选择第 ${slot+1} 个联动海克斯`:`选择候选 ${slot+1}`;$('#picker-search').value='';$('#picker-search').placeholder=kind==='champion'?'搜索英雄、称号、昵称或英文名':'搜索海克斯名称、英文或效果';renderPicker();$('#picker-dialog').showModal();setTimeout(()=>$('#picker-search').focus(),10);}
function renderPicker(){let list=picker.kind==='champion'?champions:augments.filter(isReferenceActive);const q=$('#picker-search').value;if(picker.kind==='owned')list=list.filter(a=>!state.owned.includes(a.id));if(picker.kind==='candidate')list=list.filter(a=>!state.candidates.some((id,i)=>i!==picker.slot&&id===a.id)&&!state.owned.includes(a.id));if(picker.kind==='synergy')list=list.filter(a=>!state.synergy.some((id,i)=>i!==picker.slot&&id===a.id));list=list.filter(a=>matchText(a,q));$('#picker-list').innerHTML=list.slice(0,100).map(a=>`<button class="picker-item" data-action="pick-item" data-id="${esc(a.id)}">${img(a.icon)}<span><strong>${esc(a.name)}</strong><small>${picker.kind==='champion'?esc(a.title):`${rarityNames[a.rarity]||'特殊'} · ${tags(a).slice(0,2).map(t=>TAG_LABELS[t]).join(' / ')||'效果资料'}`}</small></span></button>`).join('')||empty('没有找到符合条件的项目','已选择的项目不会重复出现。试试更短的名称或效果关键词。');if(list.length>100)$('#picker-list').insertAdjacentHTML('beforeend',`<p class="association-note" style="grid-column:1/-1">显示前 100 项；输入关键词继续缩小范围。</p>`);}
function showDetail(id){const a=augMap.get(id);if(!a)return;const r=rank(a);const pairs=augments.filter(b=>isReferenceActive(b)&&b.id!==a.id).map(b=>({b,r:getSynergy(a,b,currentChampion())})).filter(x=>['conditional','strong'].includes(x.r.level)).slice(0,3);$('#detail-content').innerHTML=`<div class="dialog-head"><span class="eyebrow">海克斯档案</span><button class="icon-button" data-action="close-detail" aria-label="关闭详情">✕</button></div><div class="dialog-body"><div class="detail-augment-title">${img(a.icon)}<div><h2>${esc(a.name)}</h2><p>${esc(a.enName)} · ${rarityNames[a.rarity]||'品质待核实'}</p></div></div><div class="detail-block"><h3>效果说明</h3>${!isReferenceActive(a)?`<p style="color:var(--gold);font-size:11px">${a.recommendable===false?'赛季之星专属取得，不属于常规随机三选一，不参与默认推荐。':a.retiredPatch?`来源标记于 ${esc(a.retiredPatch)} 退场，仅供历史查阅。`:'仅在来源目录中收录，当前可选状态未确认，不参与默认推荐。'}</p>`:''}<p>${esc(a.description||'来源暂未提供完整效果，暂不作确定推荐。')}</p>${a.unresolvedValues?.length?'<p style="color:var(--gold);font-size:11px;margin-top:8px">来源中部分数值仍为变量，占位数值待核实。请以游戏内实际说明为准。</p>':''}</div><div class="detail-block"><h3>用于当前英雄 · ${esc(currentChampion()?.name||'未选择')}</h3><ul>${r.reasons.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${r.cautions.length?`<p style="font-size:11px;color:var(--gold)">${r.cautions.map(esc).join(' ')}</p>`:''}</div>${pairs.length?`<div class="detail-block"><h3>可继续探索的条件联动</h3>${pairs.map(x=>`<button class="subtle-tag" data-action="detail-synergy" data-a="${esc(a.id)}" data-b="${esc(x.b.id)}">${esc(x.b.name)} ↗</button>`).join('')}<p style="font-size:10px;margin-top:6px">机制推导，需核对对象、冷却与特殊交互。</p></div>`:''}<div class="detail-source">可选清单版本：${esc(a.patch||data.meta.patch)}<br>效果文本版本：${esc(a.descriptionPatch||'来源未注明')}<br>英雄资源版本：${esc(getVersionInfo(data.meta).championVersion)}<br>${a.statsPatch?`选择率快照：${esc(a.statsPatch)}（不用于当前强度排名）<br>`:''}效果出处：<a href="${safeUrl(a.sourceUrl)}" target="_blank" rel="noopener noreferrer">查看海克斯原始资料 ↗</a><br>标签与推荐为本站规则推导，不是实测胜率结论。</div><div class="dialog-actions"><button class="primary-button" ${!isReferenceActive(a)&&!state.owned.includes(a.id)?'disabled':''} data-action="toggle-owned" data-id="${esc(a.id)}">${state.owned.includes(a.id)?'从本局移除':'＋ 加入已选海克斯'}</button><button class="secondary-button" data-action="detail-synergy" data-a="${esc(a.id)}">探索它的联动</button></div></div>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
function showSources(){const v=getVersionInfo(data.meta);const notes=[`海克斯清单和效果说明对应 ${v.rulesPatch} 正式服资料，并按官方公告核对新增与移除。`,"专属强化可在全部资料中查询，但不会进入普通三选一推荐。",`${augments.filter(a=>a.unresolvedValues?.length).length} 项资料含待核实的动态数值或运行时内容，未按猜测补值。`,"游戏热更新、特定英雄限制和任务进度可能影响可选状态，请以游戏内实际说明为准。","资料采用手动同步，最后更新时间表示最近一次成功同步时间。"];$('#detail-content').innerHTML=`<div class="dialog-head"><h2>数据与推荐说明</h2><button class="icon-button" data-action="close-detail" aria-label="关闭说明">✕</button></div><div class="dialog-body"><div class="source-notice">当前收录 <strong>${augments.length} 条海克斯资料、${champions.length} 位英雄</strong>。<br>其中 ${augments.filter(isReferenceActive).length} 项可用于常规选择，${augments.filter(a=>a.recommendable===false).length} 项为赛季之星专属，${augments.filter(a=>a.availability==='catalog-only').length} 项可选状态未确认，${augments.filter(a=>a.retiredPatch).length} 项已退场。<br>规则数据版本：海克斯大乱斗 ${esc(v.label)}。<br>英雄资源版本：${esc(v.championVersion)}。<br>最后更新时间：<time datetime="${esc(v.updatedAt||'')}">${esc(v.updatedLabel)}</time>。<br>来源统计版本：${esc(v.statsPatch)}；样本日期：${esc(v.statsDate)}。<br>更新时间表示本站资料同步时间，不表示统计样本日期。<br>本站适配排序与联动结论来自可解释的机制规则，尚未进行游戏实测。英雄胜率页另提供独立的来源统计，海克斯排序使用同口径的局末持有胜率差。${v.statsLag?'新版规则已更新，统计快照尚未跟上；没有将旧统计标成新版。':'各来源仍可能存在更新延迟，请以游戏内实际规则为准。'}</div><div class="source-list">${(data.meta.sources||[]).map(s=>`<div><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a><p>${esc(s.license||s.note||'请参阅来源页面的使用说明。')}</p></div>`).join('')}<div><a href="https://aramhex.com/" target="_blank" rel="noopener noreferrer">AramHex 英雄与海克斯胜率统计 ↗</a><p>独立的 16.21 正式服统计快照，国服 7 区合并。英雄胜率页仅在同来源、版本和统计范围内计算百分点差；海克斯按对局结束时持有统计，差值表示统计关联，不保证选择后提升胜率。来源数据按 <a href="https://creativecommons.org/licenses/by-nc/4.0/deed.zh-hans" target="_blank" rel="noopener noreferrer">CC BY-NC 4.0</a> 署名非商业许可提供，本站整理与中文映射。英雄胜率页的装备区仅展示图标、名称与简短效果，不提供装备组合胜率。</p></div><div><strong>推荐如何产生？</strong><p>先识别海克斯描述中的普攻、技能、治疗等机制，再结合英雄类型、玩法方向与已选海克斯判断。只有识别到“效果产出 → 触发条件”的关系时，才给出条件联动。同标签、共同收录和高选取率都不等同于已验证强度。</p></div><div><strong>哪些情况暂时无法判断？</strong><p>特殊技能改写、任务完成难度、内置冷却、实际对局阶段、阵容和复杂交互尚未完整建模。资料不足时会保留“待验证”，不补造数值或胜率。英雄资料与海克斯快照可能属于不同版本，各自保留出处。</p></div>${notes.length?`<div><strong>资料备注</strong><ul class="condition-list">${notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></div>`:''}<div><strong>本局记录</strong><p>英雄、玩法方向和已选海克斯只保存在当前浏览器。可以使用“重置”清空。独立玩家工具，未获 Riot Games 认可；游戏名称、描述、图标及原画属于各自权利人。</p></div></div></div>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!data)return;const {action,id,slot}=b.dataset;switch(action){
 case 'sources':showSources();break;
 case 'focus-home-compare':e.preventDefault();if(state.tab!=='live'){location.hash='live';render();}$('#home-compare')?.scrollIntoView({block:'start',behavior:'smooth'});break;
 case 'detail':showDetail(id);break;
 case 'close-detail':$('#detail-dialog').close();break;
 case 'close-picker':$('#picker-dialog').close();break;
 case 'pick-champion':pick('champion');break;
 case 'pick-owned':pick('owned');break;
 case 'pick-synergy':pick('synergy',Number(slot));break;
 case 'pick-candidate':pick('candidate',Number(slot));break;
 case 'pick-item':{const p=picker;$('#picker-dialog').close();if(p.kind==='champion'){liveController?.manualChampion();state.championId=id;save();}else if(p.kind==='owned'){addOwned(id);toast('已加入本局，推荐已更新');}else if(p.kind==='synergy')state.synergy[p.slot]=id;else{state.candidates[p.slot]=id;state.candidateSource='manual';state.compared=false;}render();break;}
 case 'toggle-owned':{const a=augMap.get(id);if(state.owned.includes(id)){state.owned=state.owned.filter(x=>x!==id);save();toast(`已从本局移除「${a.name}」`);}else{addOwned(id);toast(`已加入「${a.name}」，推荐已更新`);}state.candidates=state.candidates.map(x=>x===id?null:x);if(!state.candidates.every(Boolean))state.compared=false;const open=$('#detail-dialog').open;render();if(open)showDetail(id);break;}
 case 'remove-owned':state.owned=state.owned.filter(x=>x!==id);save();render();toast('已从本局移除，推荐已更新');break;
 case 'reset-session':state.buildExpanded=false;state.selectedAugmentId=null;liveController?.confirmedSelection?.();state.owned=[];state.route='auto';state.candidates=[null,null,null];state.compared=false;save();render();toast('已清空本局海克斯与玩法方向');break;
 case 'toggle-session':if(matchMedia('(max-width:760px)').matches){state.mobileExpanded=!state.mobileExpanded;render();}break;
 case 'filter-tag':state.tag=b.dataset.tag;state.limit=24;render();break;
 case 'clear-filters':state.query='';state.rarity='all';state.tag='all';state.limit=24;render();break;
 case 'load-more':state.limit+=24;renderLibraryResults();break;
 case 'toggle-champions':state.champExpanded=!state.champExpanded;render();break;
 case 'set-champion':liveController?.manualChampion();state.championId=id;save();render();toast(`当前英雄已切换为${currentChampion().name}`);break;
 case 'set-pair':state.synergy=[b.dataset.a,b.dataset.b];if(state.tab!=='synergy')location.hash='synergy';else{render();$('.main-content').scrollIntoView({block:'start',behavior:'smooth'});}break;
 case 'detail-synergy':state.synergy=[b.dataset.a,b.dataset.b||null];$('#detail-dialog').close();if(location.hash==='#synergy')render();else location.hash='synergy';break;
 case 'remove-candidate':state.candidates[Number(slot)]=null;state.compared=false;render();break;
 case 'compare':if(state.candidates.every(Boolean)){state.compared=true;render();$('.recommendation-list').scrollIntoView({block:'nearest',behavior:'smooth'});}break;
 case 'clear-candidates':state.candidates=[null,null,null];state.compared=false;render();break;
 case 'adopt-candidate':if(state.candidates.includes(id)&&addOwned(id)){state.candidates=[null,null,null];state.compared=false;state.selectedAugmentId=id;state.buildExpanded=true;liveController?.confirmedSelection?.();if(state.tab!=='live')location.hash='#live';render();$('#live-build')?.scrollIntoView({block:'start',behavior:'smooth'});$('#live-build')?.focus({preventScroll:true});toast('已记录你的选择，出装与后续海克斯已更新');}break;
}});
document.addEventListener('input',e=>{if(e.target.id==='library-search'){state.query=e.target.value;state.limit=24;renderLibraryResults();}else if(e.target.id==='champ-search'){state.champQuery=e.target.value;$('#champion-grid').innerHTML=championTiles();}else if(e.target.id==='picker-search')renderPicker();});
document.addEventListener('change',e=>{if(e.target.id==='route'){state.route=e.target.value;save();render();}else if(e.target.id==='scope-filter'){state.scope=e.target.value;state.limit=24;renderLibraryResults();}else if(e.target.id==='rarity-filter'){state.rarity=e.target.value;state.limit=24;renderLibraryResults();}else if(e.target.id==='sort-filter'){state.sort=e.target.value;renderLibraryResults();}});
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
window.addEventListener('hashchange',()=>{if(data){render();window.scrollTo({top:0,behavior:'instant'});}});
async function init(){try{const response=await fetch('./data.json',{cache:'no-store'});if(!response.ok)throw Error(`资料请求失败（${response.status}）`);const raw=await response.json();data=enrichData(raw);champions=data.champions;augments=data.augments.filter(a=>!a.isInternalTemplate);champions.forEach(c=>c.id=String(c.id));augments.forEach(a=>a.id=String(a.id));champMap=new Map(champions.map(c=>[c.id,c]));augMap=new Map(augments.map(a=>[a.id,a]));statisticsView=createStatisticsView({catalog:data});const retiredOwned=state.owned.filter(id=>augMap.has(id)&&!isReferenceActive(augMap.get(id)));state.owned=state.owned.filter(id=>augMap.has(id)&&isReferenceActive(augMap.get(id)));if(retiredOwned.length){save();toast(`已移除 ${retiredOwned.length} 个不在本版本可选清单中的旧海克斯`);}if(!champMap.has(String(state.championId)))state.championId=champions.find(c=>c.enName==='Ahri'||c.name==='阿狸')?.id||champions[0]?.id;liveController=createLiveController({getChampion:currentChampion,getGameId:()=>state.gameId,onGameId:id=>{state.gameId=id;save();},getChampionById:id=>champMap.get(id),getChampions:()=>champions,getBuildExpanded:()=>state.buildExpanded,getSelectedAugment:()=>augMap.get(state.selectedAugmentId),onBuildToggle:()=>{state.buildExpanded=!state.buildExpanded;},onLoadingPreview:()=>{state.buildExpanded=true;},getOwned:ownedAugments,getRoute:()=>state.route,getAugments:()=>augments,renderLive:()=>{const root=$('#live-content');if(root){const expanded=root.querySelector('.live-help')?.open;const focused=document.activeElement?.dataset?.liveAction;root.innerHTML=liveController.html();if(expanded)root.querySelector('.live-help').open=true;if(focused)root.querySelector(`[data-live-action="${focused}"]`)?.focus({preventScroll:true});}},onChampion:id=>{if(champMap.has(id)&&state.championId!==id){state.championId=id;save();render();}},onOffers:(ids,meta={})=>{const next=Array.from({length:3},(_,i)=>ids[i]||null);if(new Set(next).size!==3||!next.every(id=>augMap.has(id)&&isReferenceActive(augMap.get(id))&&!state.owned.includes(id)))return;if(JSON.stringify(next)===JSON.stringify(state.candidates)&&state.candidateSource==='ocr')return;state.candidates=next;state.candidateSource='ocr';state.compared=true;renderKeepingFocus();if(state.tab!=='live')toast('已识别本轮选项，回我的这一局查看');},onOffersExpired:()=>{if(state.candidateSource!=='ocr')return;state.candidates=[null,null,null];state.compared=false;state.candidateSource='manual';renderKeepingFocus();},onNewGame:()=>{state.buildExpanded=false;state.selectedAugmentId=null;state.candidateSource='manual';state.owned=[];state.candidates=[null,null,null];state.compared=false;state.route='auto';save();render();toast('检测到新对局，已清空上一局的海克斯');}});sessionSync=createSessionSync({token:sessionStorage.getItem('hexguide-local-session')||'',getState:()=>({owned:state.owned,route:state.route}),applyState:value=>{const previous=state.owned;state.owned=value.owned.filter(id=>augMap.has(id)&&isReferenceActive(augMap.get(id)));const added=state.owned.filter(id=>!previous.includes(id));if(added.length){state.selectedAugmentId=added.at(-1);state.buildExpanded=true;state.candidates=[null,null,null];state.compared=false;liveController?.confirmedSelection?.();}if(state.selectedAugmentId&&!state.owned.includes(state.selectedAugmentId))state.selectedAugmentId=state.owned.at(-1)||null;state.route=routeNames[value.route]?value.route:'auto';if(value.gameId)state.gameId=value.gameId;save();renderKeepingFocus();}});window.addEventListener('pagehide',()=>sessionSync.close(),{once:true});$('#version-label').textContent=`数据 ${getVersionInfo(data.meta).label}`;$('#loading').hidden=true;$('#app').hidden=false;render();}catch(error){$('#loading').innerHTML=`<span class="loading-rune">◇</span><h1>资料暂时未能载入</h1><p>请检查网络后重新载入。下载到本地时，需要通过本地服务打开。</p><div class="error-box">${esc(error.message)}</div><button class="secondary-button" onclick="location.reload()">重新载入</button>`;}}
init();
